from z3 import *

def solve_graceful_labeling():
    solver = Solver()
    # Set a timeout for the solver
    solver.set("timeout", 30000) # 30 seconds

    vars = [[Int(f"v_{g}_{i}") for i in range(5)] for g in range(3)]
    flat_vars = [vars[g][i] for g in range(3) for i in range(5)]

    for v in flat_vars:
        solver.add(v >= 0, v <= 40)

    solver.add(Distinct(flat_vars))

    edges = []
    for g in range(3):
        for i in range(5):
            for j in range(i + 1, 5):
                edges.append((vars[g][i], vars[g][j]))
    for g in range(2):
        for i in range(5):
            edges.append((vars[g][i], vars[g+1][i]))

    edge_labels = [Abs(u - v) for (u, v) in edges]

    solver.add(Distinct(edge_labels))
    for el in edge_labels:
        solver.add(el >= 1, el <= 40)

    if solver.check() == sat:
        model = solver.model()
        result = [model.evaluate(v).as_long() for v in flat_vars]
        return result
    else:
        return None

