import random

def get_edges(labels):
    edges = []
    for g in range(3):
        for i in range(5):
            for j in range(i + 1, 5):
                edges.append(abs(labels[g*5 + i] - labels[g*5 + j]))
    for g in range(2):
        for i in range(5):
            edges.append(abs(labels[g*5 + i] - labels[(g+1)*5 + i]))
    return edges

def solve_simulated_annealing():
    # Labels 0..40, 15 vertices
    labels = random.sample(range(41), 15)

    def cost(labels):
        edges = get_edges(labels)
        # Cost is the number of duplicate edge labels + number of edge labels outside 1..40
        # Actually, we want all 40 edges to have distinct labels in 1..40.
        # Let's use the number of unique edge labels as a cost.
        # We want 40 unique edge labels.

        unique_edges = set(edges)
        # Also check if all edges are in 1..40
        invalid_edges = [e for e in edges if e < 1 or e > 40]

        return 40 - len(unique_edges) + len(invalid_edges)

    current_cost = cost(labels)
    temp = 10.0

    for _ in range(100000):
        if current_cost == 0:
            return labels

        # Try a move
        new_labels = list(labels)
        if random.random() < 0.5:
            # Swap two labels
            i, j = random.sample(range(15), 2)
            new_labels[i], new_labels[j] = new_labels[j], new_labels[i]
        else:
            # Change one label
            i = random.randint(0, 14)
            new_label = random.randint(0, 40)
            if new_label not in new_labels:
                new_labels[i] = new_label

        new_cost = cost(new_labels)

        if new_cost < current_cost or random.random() < (current_cost - new_cost) / temp:
            labels = new_labels
            current_cost = new_cost

        temp *= 0.9999

    return None

for _ in range(5):
    result = solve_simulated_annealing()
    if result:
